fn rotate(a: &[i32], offset: usize) -> Vec<i32> {
    let n = a.len();
    if n == 0 {
        return Vec::new();
    }
    // Compute effective rotation within bounds [0, n)
    let k = offset % n;
    // If k == 0, no need to rearrange
    if k == 0 {
        return a.to_vec();
    }
    // Build a new Vec by slicing and concatenating
    let mut result = Vec::with_capacity(n);
    result.extend_from_slice(&a[k..]);
    result.extend_from_slice(&a[..k]);
    result
}

